def extract_boxed(text):
    results = []
    i = 0
    while i < len(text):
        idx = text.find("\\boxed{", i)
        if idx == -1:
            break
        depth = 0
        start = idx + len("\\boxed{")
        for j in range(start, len(text)):
            if text[j] == '{':
                depth += 1
            elif text[j] == '}':
                if depth == 0:
                    results.append(text[start:j])
                    i = j + 1
                    break
                depth -= 1
        else:
            i = len(text)
    return results[-1].strip() if results else None


def normalize_answer(ans):
    if ans is None:
        return ""
    ans = ans.strip()
    ans = re.sub(r'\\(text|mathrm|mathbf|mathit|textbf)\{([^}]*)\}', r'\2', ans)
    ans = ans.replace("\\left", "").replace("\\right", "")
    ans = re.sub(r'\\[,;:!]', '', ans)
    ans = ans.replace(" ", "")
    ans = ans.replace("\\dfrac", "\\frac").replace("\\tfrac", "\\frac")
    ans = ans.replace('^\\circ', '')
    ans = ans.replace('\\circ', '')
    ans = ans.replace('\xb0', '')
    ans = ans.replace('\\degree', '')
    ans = re.sub(r'\\sqrt(\d+)', r'\\sqrt{\1}', ans)
    ans = ans.rstrip(".")
    return ans


def _parse_radical(s):
    m = re.match(r'^(-?\d+)\\sqrt\{(\d+)\}$', s)
    if m:
        coeff, radicand = int(m.group(1)), int(m.group(2))
    else:
        m = re.match(r'^\\sqrt\{(\d+)\}$', s)
        if m:
            coeff, radicand = 1, int(m.group(1))
        else:
            return None
    i = 2
    while i * i <= radicand:
        while radicand % (i * i) == 0:
            radicand //= (i * i)
            coeff *= i
        i += 1
    return (coeff, radicand)


